    alert_te: "\u0c39\u0c46\u0c1a\u0c4d\u0c1a\u0c30\u0c3f\u0c15: \u0c17\u0c30\u0c3f\u0c37\u0c4d\u0c1f \u0c35\u0c47\u0c17 \u0c2a\u0c30\u0c3f\u0c2e\u0c3f\u0c24\u0c3f \u0c17\u0c02\u0c1f\u0c15\u0c41 100 \u0c15\u0c3f\u0c32\u0c4b\u0c2e\u0c40\u0c1f\u0c30\u0c4d\u0c32\u0c41. \u0c0e\u0c15\u0c4d\u0c38\u0c4d\u200c\u0c2a\u0c4d\u0c30\u0c46\u0c38\u0c4d\u200c\u0c35\u0c47 \u0c2e\u0c3e\u0c30\u0c4d\u0c17\u0c02.",
    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0905\u0927\u093f\u0915\u0924\u092e \u0917\u0924\u093f \u0938\u0940\u092e\u093e 100 \u0915\u093f\u0932\u094b\u092e\u0940\u091f\u0930 \u092a\u094d\u0930\u0924\u093f \u0918\u0902\u091f\u093e\u0964 \u090f\u0915\u094d\u0938\u092a\u094d\u0930\u0947\u0938\u0935\u0947 \u092e\u093e\u0930\u094d\u0917\u0964",
    meaning_en: "Maximum legal speed limit 100 km/h for passenger cars on expressways.",
    meaning_te: "\u0c0e\u0c15\u0c4d\u0c38\u0c4d\u200c\u0c2a\u0c4d\u0c30\u0c46\u0c38\u0c4d\u200c\u0c35\u0c47\u0c32\u0c2a\u0c48 \u0c15\u0c3e\u0c30\u0c4d\u0c32\u0c15\u0c41 \u0c17\u0c30\u0c3f\u0c37\u0c4d\u0c1f \u0c35\u0c47\u0c17 \u0c2a\u0c30\u0c3f\u0c2e\u0c3f\u0c24\u0c3f 100 \u0c15\u0c3f.\u0c2e\u0c40.",
    meaning_hi: "\u090f\u0915\u094d\u0938\u092a\u094d\u0930\u0947\u0938\u0935\u0947 \u092a\u0930 \u0915\u093e\u0930\u094b\u0902 \u0939\u0947\u0924\u0941 \u0905\u0927\u093f\u0915\u0924\u092e \u0915\u093e\u0928\u0942\u0928\u0940 \u0917\u0924\u093f 100 \u0915\u093f\u092e\u0940/\u0918\u0902\u091f\u093e \u0939\u0948\u0964",
    penalty_info: "\u20b91,000 \u2013 \u20b92,000 under Sec 112/183 MV Act",
    image_url: '/signs/020.png'
