    category: "CAUTIONARY",
    urgency: "WARNING",
    speed_limit: null,
    alert_en: "Caution: Steep downhill slope ahead. Use engine braking.",
    alert_te: "\u0c39\u0c46\u0c1a\u0c4d\u0c1a\u0c30\u0c3f\u0c15: \u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c24\u0c40\u0c35\u0c4d\u0c30\u0c2e\u0c48\u0c28 \u0c26\u0c3f\u0c17\u0c41\u0c21\u0c41 \u0c30\u0c4b\u0c21\u0c4d\u0c21\u0c41 \u0c09\u0c02\u0c26\u0c3f. \u0c07\u0c02\u0c1c\u0c3f\u0c28\u0c4d \u0c2c\u0c4d\u0c30\u0c47\u0c15\u0c3f\u0c02\u0c17\u0c4d \u0c09\u0c2a\u0c2f\u0c4b\u0c17\u0c3f\u0c02\u0c1a\u0c02\u0c21\u0c3f.",
    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u0924\u0940\u0935\u094d\u0930 \u0922\u0932\u093e\u0928 \u0939\u0948\u0964 \u0917\u0924\u093f \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u093f\u0924 \u0930\u0916\u0947\u0902 \u0914\u0930 \u092c\u094d\u0930\u0947\u0915 \u092a\u0930 \u0927\u094d\u092f\u093e\u0928 \u0926\u0947\u0902\u0964",
    meaning_en: "Steep downhill descent. Avoid neutral gear and use engine braking.",
    meaning_te: "\u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c32\u0c4b\u0c24\u0c48\u0c28 \u0c26\u0c3f\u0c17\u0c41\u0c21\u0c41 \u0c30\u0c4b\u0c21\u0c4d\u0c21\u0c41. \u0c28\u0c4d\u0c2f\u0c42\u0c1f\u0c4d\u0c30\u0c32\u0c4d \u0c1a\u0c47\u0c2f\u0c15\u0c41\u0c02\u0c21\u0c3e \u0c07\u0c02\u0c1c\u0c3f\u0c28\u0c4d \u0c2c\u0c4d\u0c30\u0c47\u0c15\u0c3f\u0c02\u0c17\u0c4d \u0c35\u0c3e\u0c21\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0906\u0917\u0947 \u0924\u0940\u0935\u094d\u0930 \u0922\u0932\u093e\u0928 \u0939\u0948\u0964 \u0928\u094d\u092f\u0942\u091f\u094d\u0930\u0932 \u092e\u0947\u0902 \u0928 \u091a\u0932\u093e\u090f\u0902 \u0914\u0930 \u0907\u0902\u091c\u0928 \u092c\u094d\u0930\u0947\u0915\u093f\u0902\u0917 \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964",
    penalty_info: "Advisory",
