    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u0938\u0921\u093c\u0915 \u0938\u0902\u0915\u0930\u0940 \u0939\u094b \u0930\u0939\u0940 \u0939\u0948\u0964 \u0938\u093e\u0935\u0927\u093e\u0928\u0940 \u0938\u0947 \u091a\u0932\u093e\u090f\u0902\u0964",
    meaning_en: "Roadway narrows ahead. Merge cautiously and yield if required.",
    meaning_te: "\u0c30\u0c39\u0c26\u0c3e\u0c30\u0c3f \u0c35\u0c46\u0c21\u0c32\u0c4d\u0c2a\u0c41 \u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c24\u0c17\u0c4d\u0c17\u0c41\u0c24\u0c41\u0c02\u0c26\u0c3f. \u0c0e\u0c26\u0c41\u0c30\u0c41\u0c17\u0c3e \u0c35\u0c1a\u0c4d\u0c1a\u0c47 \u0c35\u0c3e\u0c39\u0c28\u0c3e\u0c32\u0c15\u0c41 \u0c26\u0c3e\u0c30\u0c3f \u0c07\u0c35\u0c4d\u0c35\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0938\u0921\u093c\u0915 \u0906\u0917\u0947 \u0938\u0902\u0915\u0930\u0940 \u0939\u094b \u0930\u0939\u0940 \u0939\u0948\u0964 \u0938\u093e\u092e\u0928\u0947 \u0938\u0947 \u0906\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u094b \u0927\u094d\u092f\u093e\u0928 \u092e\u0947\u0902 \u0930\u0916\u0947\u0902\u0964",
