    meaning_hi: "\u0906\u0917\u0947 \u0938\u0921\u093c\u0915 \u091a\u094c\u0921\u093c\u0940 \u0939\u094b \u0930\u0939\u0940 \u0939\u0948 \u0914\u0930 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u0932\u0947\u0928 \u0916\u0941\u0932 \u0930\u0939\u0940 \u0939\u0948\u0902\u0964",
