    meaning_hi: "\u0906\u0917\u0947 \u0938\u0902\u0915\u0930\u093e \u092a\u0941\u0932 \u0939\u0948\u0964 \u092a\u0941\u0932 \u092a\u0930 \u0913\u0935\u0930\u091f\u0947\u0915\u093f\u0902\u0917 \u092c\u093f\u0932\u094d\u0915\u0941\u0932 \u0928 \u0915\u0930\u0947\u0902\u0964",
