    meaning_hi: "\u0938\u0921\u093c\u0915 \u092a\u0930 \u092b\u093f\u0938\u0932\u0928 \u0915\u093e \u0916\u0924\u0930\u093e \u0939\u0948\u0964 \u0905\u091a\u093e\u0928\u0915 \u092c\u094d\u0930\u0947\u0915 \u0928 \u0932\u0917\u093e\u090f\u0902\u0964",
