    name_te: "\u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c1f\u0c4d\u0c30\u0c3e\u0c2b\u0c3f\u0c15\u0c4d \u0c38\u0c3f\u0c17\u0c4d\u0c28\u0c32\u0c4d",
    name_hi: "\u0906\u0917\u0947 \u091f\u094d\u0930\u0948\u092b\u093f\u0915 \u0938\u093f\u0917\u094d\u0928\u0932",
    category: "CAUTIONARY",
    urgency: "WARNING",
    speed_limit: null,
    alert_en: "Notice: Traffic signal ahead. Prepare to stop if light turns red.",
    alert_te: "\u0c39\u0c46\u0c1a\u0c4d\u0c1a\u0c30\u0c3f\u0c15: \u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c1f\u0c4d\u0c30\u0c3e\u0c2b\u0c3f\u0c15\u0c4d \u0c32\u0c48\u0c1f\u0c4d\u0c32\u0c41 \u0c09\u0c28\u0c4d\u0c28\u0c3e\u0c2f\u0c3f. \u0c06\u0c17\u0c21\u0c3e\u0c28\u0c3f\u0c15\u0c3f \u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c02\u0c17\u0c3e \u0c09\u0c02\u0c21\u0c02\u0c21\u0c3f.",
    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u091f\u094d\u0930\u0948\u092b\u093f\u0915 \u0932\u093e\u0907\u091f \u0939\u0948\u0964 \u0930\u0941\u0915\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0924\u0948\u092f\u093e\u0930 \u0930\u0939\u0947\u0902\u0964",
    meaning_en: "Traffic light regulated intersection ahead. Be prepared to halt.",
    meaning_te: "\u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c1f\u0c4d\u0c30\u0c3e\u0c2b\u0c3f\u0c15\u0c4d \u0c38\u0c3f\u0c17\u0c4d\u0c28\u0c32\u0c4d \u0c32\u0c48\u0c1f\u0c4d\u0c32\u0c41 \u0c09\u0c28\u0c4d\u0c28\u0c3e\u0c2f\u0c3f. \u0c30\u0c46\u0c21\u0c4d \u0c32\u0c48\u0c1f\u0c4d \u0c2a\u0c21\u0c3f\u0c24\u0c47 \u0c06\u0c17\u0c21\u0c3e\u0c28\u0c3f\u0c15\u0c3f \u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c02\u0c17\u0c3e \u0c09\u0c02\u0c21\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0906\u0917\u0947 \u091f\u094d\u0930\u0948\u092b\u093f\u0915 \u0938\u093f\u0917\u094d\u0928\u0932 \u0939\u0948\u0964 \u0932\u093e\u0932 \u092c\u0924\u094d\u0924\u0940 \u0939\u094b\u0928\u0947 \u092a\u0930 \u0930\u0941\u0915\u0928\u0947 \u0915\u094b \u0924\u0948\u092f\u093e\u0930 \u0930\u0939\u0947\u0902\u0964",
    penalty_info: "Advisory",
    image_url: '/signs/062.png'
