    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0938\u0921\u093c\u0915 \u092a\u0930 \u092e\u0935\u0947\u0936\u0940 \u0906 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u0938\u093e\u0935\u0927\u093e\u0928\u0940 \u0938\u0947 \u091a\u0932\u0947\u0902\u0964",
    meaning_en: "Stray cattle or livestock likely to cross the highway.",
    meaning_te: "\u0c30\u0c39\u0c26\u0c3e\u0c30\u0c3f\u0c2a\u0c48 \u0c2a\u0c36\u0c41\u0c35\u0c41\u0c32\u0c41 \u0c05\u0c15\u0c38\u0c4d\u0c2e\u0c3e\u0c24\u0c4d\u0c24\u0c41\u0c17\u0c3e \u0c35\u0c1a\u0c4d\u0c1a\u0c47 \u0c2a\u0c4d\u0c30\u0c2e\u0c3e\u0c26\u0c02 \u0c09\u0c02\u0c26\u0c3f. \u0c1c\u0c3e\u0c17\u0c4d\u0c30\u0c24\u0c4d\u0c24\u0c17\u0c3e \u0c28\u0c21\u0c2a\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0938\u0921\u093c\u0915 \u092a\u0930 \u092a\u0936\u0941 \u0906 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u0938\u0924\u0930\u094d\u0915\u0924\u093e \u0938\u0947 \u0935\u093e\u0939\u0928 \u091a\u0932\u093e\u090f\u0902\u0964",
    penalty_info: "Advisory",
