    name_te: "\u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c2c\u0c3e\u0c30\u0c3f\u0c15\u0c47\u0c21\u0c4d / \u0c1f\u0c4b\u0c32\u0c4d",
    name_hi: "\u0906\u0917\u0947 \u092c\u0948\u0930\u093f\u092f\u0930",
    category: "CAUTIONARY",
    urgency: "WARNING",
    speed_limit: null,
    alert_en: "Caution: Toll barrier or checkpoint ahead. Prepare to halt.",
    alert_te: "\u0c39\u0c46\u0c1a\u0c4d\u0c1a\u0c30\u0c3f\u0c15: \u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c1f\u0c4b\u0c32\u0c4d \u0c2c\u0c3e\u0c30\u0c3f\u0c15\u0c47\u0c21\u0c4d \u0c32\u0c47\u0c26\u0c3e \u0c17\u0c47\u0c1f\u0c41 \u0c09\u0c02\u0c26\u0c3f. \u0c35\u0c47\u0c17\u0c3e\u0c28\u0c4d\u0c28\u0c3f \u0c24\u0c17\u0c4d\u0c17\u0c3f\u0c02\u0c1a\u0c02\u0c21\u0c3f.",
    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u091f\u094b\u0932 \u092c\u0948\u0930\u093f\u092f\u0930 \u092f\u093e \u091a\u0947\u0915\u092a\u094b\u0938\u094d\u091f \u0917\u0947\u091f \u0939\u0948\u0964 \u0917\u0924\u093f \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902\u0964",
    meaning_en: "Toll barrier or security checkpoint ahead. Reduce speed.",
    meaning_te: "\u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c1f\u0c4b\u0c32\u0c4d \u0c2a\u0c4d\u0c32\u0c3e\u0c1c\u0c3e \u0c32\u0c47\u0c26\u0c3e \u0c2a\u0c4b\u0c32\u0c40\u0c38\u0c41 \u0c1a\u0c46\u0c15\u0c4d\u200c\u0c2a\u0c4b\u0c38\u0c4d\u0c1f\u0c4d \u0c2c\u0c3e\u0c30\u0c3f\u0c15\u0c47\u0c21\u0c4d \u0c09\u0c02\u0c26\u0c3f. \u0c35\u0c47\u0c17\u0c02 \u0c24\u0c17\u0c4d\u0c17\u0c3f\u0c02\u0c1a\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0906\u0917\u0947 \u091f\u094b\u0932 \u0928\u093e\u0915\u093e \u092f\u093e \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u091a\u0947\u0915\u092a\u094b\u0938\u094d\u091f \u092c\u0948\u0930\u093f\u092f\u0930 \u0939\u0948\u0964 \u0917\u0924\u093f \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902\u0964",
