    name_te: "\u0c30\u0c4b\u0c21\u0c4d\u0c21\u0c41 \u0c2a\u0c28\u0c3f \u0c1c\u0c30\u0c41\u0c17\u0c41\u0c24\u0c4b\u0c02\u0c26\u0c3f",
    name_hi: "\u0915\u093e\u0930\u094d\u092f \u092a\u094d\u0930\u0917\u0924\u093f \u092a\u0930 \u0939\u0948",
    category: "CAUTIONARY",
    urgency: "WARNING",
    speed_limit: null,
    alert_en: "Caution: Road construction workers ahead. Drive slowly.",
    alert_te: "\u0c39\u0c46\u0c1a\u0c4d\u0c1a\u0c30\u0c3f\u0c15: \u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c30\u0c4b\u0c21\u0c4d\u0c21\u0c41 \u0c28\u0c3f\u0c30\u0c4d\u0c2e\u0c3e\u0c23 \u0c2a\u0c28\u0c3f \u0c1c\u0c30\u0c41\u0c17\u0c41\u0c24\u0c4b\u0c02\u0c26\u0c3f. \u0c28\u0c46\u0c2e\u0c4d\u0c2e\u0c26\u0c3f\u0c17\u0c3e \u0c28\u0c21\u0c2a\u0c02\u0c21\u0c3f.",
    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u0938\u0921\u093c\u0915 \u092e\u0930\u092e\u094d\u092e\u0924 \u0915\u093e\u0930\u094d\u092f \u091c\u093e\u0930\u0940 \u0939\u0948\u0964 \u0917\u0924\u093f \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u093f\u0924 \u0930\u0916\u0947\u0902\u0964",
    meaning_en: "Road maintenance or construction zone ahead. Follow lane signs.",
    meaning_te: "\u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c30\u0c4b\u0c21\u0c4d\u0c21\u0c41 \u0c2e\u0c30\u0c2e\u0c4d\u0c2e\u0c24\u0c4d\u0c24\u0c41 \u0c2a\u0c28\u0c41\u0c32\u0c41 \u0c1c\u0c30\u0c41\u0c17\u0c41\u0c24\u0c41\u0c28\u0c4d\u0c28\u0c3e\u0c2f\u0c3f. \u0c35\u0c30\u0c4d\u0c15\u0c30\u0c4d\u0c32\u0c28\u0c41 \u0c17\u0c2e\u0c28\u0c3f\u0c38\u0c4d\u0c24\u0c42 \u0c28\u0c46\u0c2e\u0c4d\u0c2e\u0c26\u0c3f\u0c17\u0c3e \u0c35\u0c46\u0c33\u0c4d\u0c33\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0938\u0921\u093c\u0915 \u092a\u0930 \u092e\u091c\u0926\u0942\u0930 \u0915\u093e\u092e \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902\u0964 \u0917\u0924\u093f \u0927\u0940\u092e\u0940 \u0930\u0916\u0947\u0902 \u0914\u0930 \u0928\u093f\u0930\u094d\u0926\u0947\u0936\u094b\u0902 \u0915\u093e \u092a\u093e\u0932\u0928 \u0915\u0930\u0947\u0902\u0964",
