    category: "CAUTIONARY",
    urgency: "WARNING",
    speed_limit: null,
    alert_en: "Notice: Roundabout ahead. Yield to traffic in circle.",
    alert_te: "\u0c39\u0c46\u0c1a\u0c4d\u0c1a\u0c30\u0c3f\u0c15: \u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c30\u0c4c\u0c02\u0c21\u0c4d\u200c\u0c0e\u0c2c\u0c4c\u0c1f\u0c4d \u0c09\u0c02\u0c26\u0c3f. \u0c15\u0c41\u0c21\u0c3f\u0c35\u0c48\u0c2a\u0c41 \u0c35\u0c3e\u0c39\u0c28\u0c3e\u0c32\u0c15\u0c41 \u0c26\u0c3e\u0c30\u0c3f \u0c07\u0c35\u0c4d\u0c35\u0c02\u0c21\u0c3f.",
    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u0917\u094b\u0932 \u091a\u0915\u094d\u0915\u0930 \u0939\u0948\u0964 \u0926\u093e\u0908\u0902 \u0913\u0930 \u0915\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u094b \u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915\u0924\u093e \u0926\u0947\u0902\u0964",
    meaning_en: "Circular roundabout ahead. Yield right-of-way to vehicles on your right.",
    meaning_te: "\u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c30\u0c4c\u0c02\u0c21\u0c4d\u200c\u0c0e\u0c2c\u0c4c\u0c1f\u0c4d \u0c38\u0c30\u0c4d\u0c15\u0c3f\u0c32\u0c4d \u0c09\u0c02\u0c26\u0c3f. \u0c38\u0c30\u0c4d\u0c15\u0c3f\u0c32\u0c4d\u200c\u0c32\u0c4b \u0c24\u0c3f\u0c30\u0c3f\u0c17\u0c47 \u0c15\u0c41\u0c21\u0c3f\u0c35\u0c48\u0c2a\u0c41 \u0c35\u0c3e\u0c39\u0c28\u0c3e\u0c32\u0c15\u0c41 \u0c26\u0c3e\u0c30\u0c3f \u0c07\u0c35\u0c4d\u0c35\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0906\u0917\u0947 \u0917\u094b\u0932 \u091a\u0915\u094d\u0915\u0930 \u0939\u0948\u0964 \u0905\u092a\u0928\u0947 \u0926\u093e\u0908\u0902 \u0913\u0930 \u0938\u0947 \u0906 \u0930\u0939\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u094b \u092a\u0939\u0932\u0947 \u091c\u093e\u0928\u0947 \u0926\u0947\u0902\u0964",
    penalty_info: "Advisory",
    image_url: '/signs/068.png'
