    name_hi: "\u0916\u0924\u0930\u0928\u093e\u0915 \u0917\u0921\u094d\u0922\u093e",
    category: "CAUTIONARY",
    urgency: "WARNING",
    speed_limit: null,
    alert_en: "Caution: Dangerous dip in road ahead. Reduce speed.",
    alert_te: "\u0c39\u0c46\u0c1a\u0c4d\u0c1a\u0c30\u0c3f\u0c15: \u0c30\u0c4b\u0c21\u0c4d\u0c21\u0c41\u0c2a\u0c48 \u0c32\u0c4b\u0c24\u0c48\u0c28 \u0c2a\u0c32\u0c4d\u0c32\u0c02 \u0c32\u0c47\u0c26\u0c3e \u0c17\u0c41\u0c02\u0c24 \u0c09\u0c02\u0c26\u0c3f. \u0c35\u0c47\u0c17\u0c02 \u0c24\u0c17\u0c4d\u0c17\u0c3f\u0c02\u0c1a\u0c02\u0c21\u0c3f.",
    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0938\u0921\u093c\u0915 \u092a\u0930 \u0917\u0939\u0930\u093e \u0917\u0921\u094d\u0922\u093e \u092f\u093e \u0922\u0932\u093e\u0928 \u0939\u0948\u0964 \u0917\u0924\u093f \u0924\u0941\u0930\u0902\u0924 \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902\u0964",
    meaning_en: "Sharp depression in road surface ahead. Slow down to avoid bottoming out.",
    meaning_te: "\u0c30\u0c4b\u0c21\u0c4d\u0c21\u0c41\u0c2a\u0c48 \u0c32\u0c4b\u0c24\u0c48\u0c28 \u0c2a\u0c32\u0c4d\u0c32\u0c02 \u0c32\u0c47\u0c26\u0c3e \u0c17\u0c41\u0c02\u0c24 \u0c09\u0c02\u0c26\u0c3f. \u0c38\u0c38\u0c4d\u0c2a\u0c46\u0c28\u0c4d\u0c37\u0c28\u0c4d \u0c26\u0c46\u0c2c\u0c4d\u0c2c\u0c24\u0c3f\u0c28\u0c15\u0c41\u0c02\u0c21\u0c3e \u0c35\u0c47\u0c17\u0c02 \u0c24\u0c17\u0c4d\u0c17\u0c3f\u0c02\u0c1a\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0938\u0921\u093c\u0915 \u092a\u0930 \u0917\u0939\u0930\u093e \u0917\u0921\u094d\u0922\u093e \u0939\u0948\u0964 \u0917\u093e\u0921\u093c\u0940 \u0915\u0947 \u0928\u093f\u091a\u0932\u0947 \u0939\u093f\u0938\u094d\u0938\u0947 \u0915\u094b \u0928\u0941\u0915\u0938\u093e\u0928 \u0938\u0947 \u092c\u091a\u093e\u0928\u0947 \u0939\u0947\u0924\u0941 \u0917\u0924\u093f \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902\u0964",
