    category: "CAUTIONARY",
    urgency: "WARNING",
    speed_limit: null,
    alert_en: "Caution: Gap in median ahead. Watch for turning vehicles.",
    alert_te: "\u0c39\u0c46\u0c1a\u0c4d\u0c1a\u0c30\u0c3f\u0c15: \u0c21\u0c3f\u0c35\u0c48\u0c21\u0c30\u0c4d \u0c2e\u0c27\u0c4d\u0c2f \u0c16\u0c3e\u0c33\u0c40 \u0c09\u0c02\u0c26\u0c3f. \u0c24\u0c3f\u0c30\u0c3f\u0c17\u0c47 \u0c35\u0c3e\u0c39\u0c28\u0c3e\u0c32 \u0c2a\u0c1f\u0c4d\u0c32 \u0c1c\u0c3e\u0c17\u0c4d\u0c30\u0c24\u0c4d\u0c24.",
    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u0921\u093f\u0935\u093e\u0907\u0921\u0930 \u092e\u0947\u0902 \u0915\u091f \u0939\u0948\u0964 \u092e\u0941\u0921\u093c\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0938\u0947 \u0938\u0924\u0930\u094d\u0915 \u0930\u0939\u0947\u0902\u0964",
    meaning_en: "Break in central divider ahead. Watch for vehicles U-turning or entering.",
    meaning_te: "\u0c30\u0c4b\u0c21\u0c4d\u0c21\u0c41 \u0c21\u0c3f\u0c35\u0c48\u0c21\u0c30\u0c4d \u0c2e\u0c27\u0c4d\u0c2f \u0c15\u0c1f\u0c4d \u0c09\u0c02\u0c26\u0c3f. \u0c2e\u0c32\u0c41\u0c2a\u0c41 \u0c24\u0c40\u0c38\u0c41\u0c15\u0c41\u0c28\u0c47 \u0c35\u0c3e\u0c39\u0c28\u0c3e\u0c32\u0c28\u0c41 \u0c17\u0c2e\u0c28\u0c3f\u0c02\u0c1a\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0921\u093f\u0935\u093e\u0907\u0921\u0930 \u092e\u0947\u0902 \u0915\u091f \u0939\u0948\u0964 \u092f\u0942-\u091f\u0930\u094d\u0928 \u0932\u0947\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0938\u0947 \u0938\u093e\u0935\u0927\u093e\u0928 \u0930\u0939\u0947\u0902\u0964",
