    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u091a\u094c\u0930\u093e\u0939\u093e \u0939\u0948\u0964 \u0917\u0924\u093f \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0938\u092d\u0940 \u0926\u093f\u0936\u093e\u0913\u0902 \u092e\u0947\u0902 \u0926\u0947\u0916\u0947\u0902\u0964",
    meaning_en: "Four-way intersection ahead where paths cross. Slow down and check lanes.",
    meaning_te: "\u0c2e\u0c41\u0c02\u0c26\u0c41 \u0c28\u0c3e\u0c32\u0c41\u0c17\u0c41 \u0c30\u0c4b\u0c21\u0c4d\u0c32\u0c41 \u0c15\u0c32\u0c3f\u0c38\u0c47 \u0c15\u0c42\u0c21\u0c32\u0c3f \u0c09\u0c02\u0c26\u0c3f. \u0c05\u0c28\u0c4d\u0c28\u0c3f \u0c35\u0c48\u0c2a\u0c41\u0c32\u0c3e \u0c1a\u0c42\u0c38\u0c3f \u0c38\u0c41\u0c30\u0c15\u0c4d\u0c37\u0c3f\u0c24\u0c02\u0c17\u0c3e \u0c26\u0c3e\u0c1f\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0906\u0917\u0947 \u091a\u093e\u0930 \u0930\u093e\u0938\u094d\u0924\u094b\u0902 \u0915\u093e \u091a\u094c\u0930\u093e\u0939\u093e \u0939\u0948\u0964 \u0917\u0924\u093f \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902 \u0914\u0930 \u091a\u093e\u0930\u094b\u0902 \u0924\u0930\u092b \u0926\u0947\u0916\u0915\u0930 \u0906\u0917\u0947 \u092c\u0922\u093c\u0947\u0902\u0964",
