    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u0925\u094b\u0921\u093c\u0940 \u0926\u0942\u0930\u0940 \u092a\u0930 \u0926\u093e\u090f\u0902-\u092c\u093e\u090f\u0902 \u092e\u094b\u0921\u093c \u0939\u0948\u0902\u0964 \u0917\u0924\u093f \u0927\u0940\u092e\u0940 \u0930\u0916\u0947\u0902\u0964",
    meaning_en: "Staggered side roads join ahead at close intervals. Drive carefully.",
    meaning_te: "\u0c15\u0c4a\u0c26\u0c4d\u0c26\u0c3f \u0c26\u0c42\u0c30\u0c02\u0c32\u0c4b\u0c28\u0c47 \u0c0e\u0c21\u0c2e \u0c2e\u0c30\u0c3f\u0c2f\u0c41 \u0c15\u0c41\u0c21\u0c3f\u0c35\u0c48\u0c2a\u0c41 \u0c38\u0c48\u0c21\u0c4d \u0c30\u0c4b\u0c21\u0c4d\u0c32\u0c41 \u0c09\u0c28\u0c4d\u0c28\u0c3e\u0c2f\u0c3f. \u0c1c\u0c3e\u0c17\u0c4d\u0c30\u0c24\u0c4d\u0c24\u0c17\u0c3e \u0c28\u0c21\u0c2a\u0c02\u0c21\u0c3f.",
    meaning_hi: "\u0906\u0917\u0947 \u0925\u094b\u0921\u093c\u0940 \u0926\u0942\u0930\u0940 \u092a\u0930 \u0926\u093e\u090f\u0902 \u0935 \u092c\u093e\u090f\u0902 \u092e\u094b\u0921\u093c \u0939\u0948\u0902\u0964 \u0938\u093e\u0935\u0927\u093e\u0928\u0940 \u0938\u0947 \u091a\u0932\u0947\u0902\u0964",
