    meaning_hi: "\u0906\u0917\u0947 \u092e\u0941\u0916\u094d\u092f \u0930\u093e\u091c\u092e\u093e\u0930\u094d\u0917 \u092e\u093f\u0932 \u0930\u0939\u093e \u0939\u0948\u0964 \u092e\u0941\u0916\u094d\u092f \u0938\u0921\u093c\u0915 \u0915\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u094b \u092a\u0939\u0932\u0947 \u091c\u093e\u0928\u0947 \u0926\u0947\u0902\u0964",
