    alert_hi: "\u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0906\u0917\u0947 \u0917\u0947\u091f \u0935\u093e\u0932\u093e \u0930\u0947\u0932\u0935\u0947 \u0915\u094d\u0930\u0949\u0938\u093f\u0902\u0917 \u0939\u0948\u0964 \u092c\u0948\u0930\u093f\u092f\u0930 \u092c\u0902\u0926 \u0939\u094b\u0928\u0947 \u092a\u0930 \u0930\u0941\u0915\u0947\u0902\u0964",
    meaning_en: "Railway level crossing with gates ahead. Halt if barrier is closing.",
