    meaning_hi: "\u0906\u0917\u0947 \u0930\u0947\u0932\u0935\u0947 \u092b\u093e\u091f\u0915 \u0939\u0948\u0964 \u092b\u093e\u091f\u0915 \u092c\u0902\u0926 \u0939\u094b\u0928\u0947 \u092f\u093e \u0932\u093e\u0932 \u092c\u0924\u094d\u0924\u0940 \u092a\u0930 \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0930\u0941\u0915\u0947\u0902\u0964",
