/**
 * Retrieves the channelized voice alert for any of the 108 Indian RTO road signs.
 * Strictly looks up the designated linguistic translation (English, Telugu, Hindi)
 * for the exact sign identity without any generic grouping fallbacks.
 */
export function getChannelizedAlert(
  classId: number,
  lang: 'en' | 'te' | 'hi' = 'en'
): { prompt: string; urgency: 'CRITICAL' | 'WARNING' | 'INFORMATIONAL'; sign: ChannelizedSignItem } | null {
  const item = CHANNELIZED_SIGNS_108[classId];
  if (!item) return null;
  const prompt = lang === 'te' ? item.alert_te : (lang === 'hi' ? item.alert_hi : item.alert_en);
  return { prompt, urgency: item.urgency, sign: item };
}

